entries[75141] = { ["name"] = "Traum vom Himmelswall", ["text"] = "Wirken in 1.5 sek. 7 tagen Abklingzeit\nReagenzien:\nGlutseidenballen (8), Flüchtige Luft (30)\nNutzt den Stoff und die Elemente der Luft, um ein Stück Traumstoff zu weben. Dieses Traumstoffmuster kann nur ein Mal pro Woche verwendet werden.\nBerufsausbilder:\nSchneiderei des Kataklysmus (65)\nKosten:\n2\n75\n\nTraumstoff\nWird beim Aufheben gebunden\nHandwerksmaterial" }
