entries[75596] = { ["name"] = "Fliegender Frostteppich", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen fliegenden Frostteppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Ich kann mich noch an meinen ersten fliegenden Teppich erinnern... Yetihaar und Leinen. Keineswegs so angenehm wie dieser hier. - Frozo der Wohlbekannte\"\nBeruf:\nSchneidern" }
entries[75597] = { ["name"] = "Fliegender Frostteppich", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nMondgespinst , Zaubertuch , Schwarztuch , Gefrorene Kugel (4)\nVerkäufer:\nFrozo der Wohlbekannte\nZone:\nKristallsangwald\nKosten:\n6\n\nFliegender Frostteppich\nWird beim Aufheben gebunden\nReittier (Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen fliegenden Frostteppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigt Schneiderei von Nordend\n(1)\nBenötigt Unerfahrenes Reiten\n\n\"Ich kann mich noch an meinen ersten fliegenden Teppich erinnern... Yetihaar und Leinen. Keineswegs so angenehm wie dieser hier. - Frozo der Wohlbekannte\"\nBeruf:\nSchneidern" }
